@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800;900&family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#101510;--panel:#171d16;--cream:#f1eee1;--muted:#92988c;--orange:#f36b35;--lime:#c8f169;--line:#343b31;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:'DM Sans',sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--cream);font-family:var(--body);min-height:100vh;background-image:radial-gradient(ellipse at 18% 0%,rgba(112,132,71,.12),transparent 35%),radial-gradient(rgba(255,255,255,.025) .7px,transparent .7px);background-size:auto,5px 5px}button{font:inherit;color:inherit}.app-shell{width:min(1120px,100%);margin:0 auto;padding:0 40px}.topbar{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--cream);font:800 16px var(--body);letter-spacing:.13em}.brand-mark{width:26px;height:26px;display:grid;place-items:center;background:var(--orange);color:#171510;font:900 20px var(--display);transform:skew(-8deg)}.brand-dot{color:var(--orange)}.top-tag,.eyebrow,.stat-label,.reset-button,.best-pill,.gesture-hint b,.shoot-button,.overlay-foot,.side-kicker,.side-metrics span,.side-tip b,.side-bottom,footer{font-family:var(--mono);letter-spacing:.11em}.top-tag{color:#a7ad9e;font-size:10px;display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px var(--lime)}.tag-divider{color:#51594d}.icon-button{width:34px;height:34px;background:transparent;border:1px solid var(--line);border-radius:50%;font-size:17px;color:var(--lime);cursor:pointer}.game-layout{display:grid;grid-template-columns:minmax(0,690px) 1fr;gap:62px;padding:33px 0 28px}.game-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:17px}.eyebrow{font-size:9px;color:var(--lime);margin:0 0 6px}.game-heading h1{font:800 42px/.9 var(--display);letter-spacing:.035em;margin:0}.game-heading h1 span{color:var(--orange)}.reset-button{background:none;border:0;color:#a6ac9c;font-size:11px;cursor:pointer;padding:9px 0}.reset-button:hover{color:var(--cream)}.scoreboard{height:82px;background:#1a2019;border:1px solid #30382d;display:flex;align-items:center;position:relative;padding:0 21px;gap:22px;margin-bottom:10px}.score-block,.clock-block,.streak-block{display:flex;flex-direction:column;gap:1px}.stat-label{font-size:8px;color:#92988c}.score-block strong,.clock-block strong,.streak-block strong{font:800 32px/.95 var(--display);letter-spacing:.02em}.score-block strong{color:var(--lime)}.clock-block strong{font-size:27px}.seconds{font-size:13px;color:#adb2a7;margin-left:2px}.streak-block strong{font-size:25px}.flame{color:var(--orange);font-size:15px;margin-left:4px}.score-divider{width:1px;height:34px;background:#3a4137}.best-pill{margin-left:auto;border:1px solid #444c3f;background:#20271d;padding:7px 10px;display:flex;gap:9px;align-items:center;font-size:8px;color:#a8ae9e}.best-pill b{color:var(--lime);font-size:12px;font-weight:500}.court-wrap{width:100%;position:relative;overflow:hidden;background:#d98a50;box-shadow:0 15px 40px #0005;touch-action:none;user-select:none}.court-wrap:after{content:'';position:absolute;inset:0;border:1px solid #ffffff27;pointer-events:none}.court-wrap canvas{display:block;width:100%;height:auto;aspect-ratio:420/570;touch-action:none;cursor:crosshair}.court-vignette{position:absolute;inset:0;box-shadow:inset 0 0 50px #44251928;pointer-events:none}.game-overlay{position:absolute;inset:0;z-index:3;display:grid;place-items:center;background:rgba(15,20,15,.53);backdrop-filter:blur(3px);transition:opacity .25s,visibility .25s}.game-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{width:min(330px,84%);padding:26px 26px 23px;text-align:center;background:#171d16;border:1px solid #49513e;box-shadow:0 16px 45px #0007;position:relative}.overlay-card:before,.overlay-card:after{content:'';position:absolute;width:18px;height:18px;border-color:var(--lime);border-style:solid}.overlay-card:before{left:-1px;top:-1px;border-width:2px 0 0 2px}.overlay-card:after{right:-1px;bottom:-1px;border-width:0 2px 2px 0}.overlay-icon{font-size:29px;margin-bottom:4px}.overlay-card .eyebrow{font-size:8px}.overlay-card h2{font:800 47px/.82 var(--display);letter-spacing:.025em;margin:12px 0}.overlay-card h2 span{color:var(--orange)}.overlay-copy{max-width:230px;color:#aeb3a7;font-size:11px;line-height:1.55;margin:13px auto 18px}.play-button{height:43px;width:100%;padding:0 15px;border:0;background:var(--lime);color:#182012;display:flex;align-items:center;justify-content:space-between;cursor:pointer;font:800 12px var(--mono);letter-spacing:.11em;transition:background .15s,transform .15s}.play-button:hover{background:#d9ff92;transform:translateY(-1px)}.play-button b{font-size:18px}.overlay-foot{display:block;color:#747d6d;font-size:7px;margin-top:13px}.feedback{position:absolute;z-index:2;top:24%;left:0;right:0;text-align:center;font:800 46px/.9 var(--display);letter-spacing:.04em;color:var(--lime);text-shadow:0 3px 14px #0008;opacity:0;transform:translateY(12px);pointer-events:none}.feedback.show{animation:feedback .9s ease forwards}.feedback.miss{color:#fff}.feedback small{display:block;font:500 9px var(--mono);letter-spacing:.18em;margin-top:5px}@keyframes feedback{0%{opacity:0;transform:translateY(12px)}20%{opacity:1;transform:translateY(0)}70%{opacity:1}100%{opacity:0;transform:translateY(-10px)}}.game-controls{height:66px;display:flex;justify-content:space-between;align-items:center}.gesture-hint{display:flex;gap:10px;align-items:center}.gesture-icon{width:28px;height:28px;border:1px solid #394233;border-radius:50%;display:grid;place-items:center;color:var(--lime);font-size:17px}.gesture-hint b{display:block;font-size:8px;color:#e3e5da}.gesture-hint small{display:block;font-size:9px;color:#858d7e;margin-top:3px}.shoot-button{height:38px;min-width:126px;padding:0 13px;background:var(--orange);border:0;color:#191810;display:flex;align-items:center;justify-content:space-between;gap:22px;font-size:10px;font-weight:500;cursor:pointer;transition:all .15s}.shoot-button:hover:not(:disabled){background:#ff8956;transform:translateY(-1px)}.shoot-button:disabled{opacity:.42;cursor:not-allowed}.shoot-arrow{font:20px var(--body)}.side-panel{padding-top:17px;display:flex;flex-direction:column;min-height:100%}.side-kicker{font-size:9px;color:#9da493}.side-kicker span{color:var(--orange);margin-right:9px}.side-rule{height:1px;background:var(--line);margin:16px 0 22px}.side-panel h2{font:800 clamp(47px,5vw,67px)/.8 var(--display);letter-spacing:.02em;margin:0}.side-panel h2 em{font-style:normal;color:var(--orange)}.side-copy{font-size:12px;color:#a3a99b;line-height:1.6;max-width:210px;margin:20px 0 30px}.side-metrics{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:15px 0;display:grid;grid-template-columns:1fr 1fr;gap:10px}.side-metrics div{display:flex;flex-direction:column;gap:6px}.side-metrics span{font-size:7px;color:#92998b;white-space:nowrap}.side-metrics b{font:800 25px/.9 var(--display);color:var(--lime)}.side-metrics small{font:9px var(--mono);color:#9ba191}.side-tip{display:flex;gap:10px;padding:18px 0;color:#a0a698;font-size:10px;line-height:1.6}.tip-star{color:var(--orange);font-size:19px;line-height:1.1}.side-tip p{margin:0}.side-tip b{font-size:8px;color:var(--cream);font-weight:500}.side-bottom{margin-top:auto;border-top:1px solid var(--line);padding-top:15px;display:flex;align-items:center;justify-content:space-between;color:#747c6d;font-size:7px}.court-lines{font-size:15px;color:var(--orange);letter-spacing:-.25em;padding-right:6px}footer{height:48px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;color:#697163;font-size:7px}footer b{color:var(--orange);font-size:10px}
@media(max-width:850px){.app-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 230px;gap:32px}.side-panel h2{font-size:53px}.scoreboard{gap:14px;padding:0 15px}}
@media(max-width:650px){body{min-height:100dvh}.app-shell{padding:0 16px}.topbar{height:56px}.brand{font-size:14px}.top-tag{font-size:8px}.game-layout{display:block;padding:18px 0 14px}.game-heading{margin-bottom:12px}.game-heading h1{font-size:36px}.scoreboard{height:68px;padding:0 13px;gap:12px;margin-bottom:8px}.score-block strong{font-size:28px}.clock-block strong{font-size:24px}.streak-block strong{font-size:22px}.score-divider{height:29px}.stat-label{font-size:7px}.best-pill{padding:6px 7px;gap:5px}.best-pill b{font-size:10px}.court-wrap{max-height:calc(100dvh - 255px);display:flex;justify-content:center}.court-wrap canvas{width:auto;height:auto;max-height:calc(100dvh - 255px);max-width:100%;object-fit:contain;aspect-ratio:420/570}.game-controls{height:58px}.shoot-button{height:36px;min-width:115px}.side-panel{display:none}footer{height:38px;font-size:6px}.overlay-card{padding:21px 20px 18px}.overlay-icon{font-size:25px}.overlay-card h2{font-size:41px}.overlay-copy{font-size:10px;margin:10px auto 14px}.play-button{height:39px}}
@media(max-height:700px) and (max-width:650px){.game-layout{padding-top:11px}.game-heading h1{font-size:31px}.game-heading{margin-bottom:8px}.scoreboard{height:59px}.court-wrap{max-height:calc(100dvh - 216px)}.court-wrap canvas{max-height:calc(100dvh - 216px)}.game-controls{height:51px}.topbar{height:49px}.overlay-card{transform:scale(.88)}}

(() => {
  const canvas = document.querySelector('#court');
  const ctx = canvas.getContext('2d');
  const overlay = document.querySelector('#overlay');
  const playButton = document.querySelector('#playButton');
  const shootButton = document.querySelector('#shootButton');
  const scoreEl = document.querySelector('#score');
  const timerEl = document.querySelector('#timer');
  const streakEl = document.querySelector('#streak');
  const bestEl = document.querySelector('#best');
  const feedback = document.querySelector('#feedback');
  const soundButton = document.querySelector('#soundButton');
  const soundIcon = document.querySelector('#soundIcon');
  const W = 420, H = 570;
  const ball = { x: 210, y: 465 };
  const hoop = { x: 210, y: 152 };
  let state = 'ready', score = 0, streak = 0, timeLeft = 60;
  let best = Number(localStorage.getItem('buckets-best') || 0);
  let pointer = null, dragging = false, shot = null, lastFrame = 0, soundOn = false;
  let lastAim = { x: hoop.x, y: hoop.y };
  bestEl.textContent = String(best).padStart(2, '0');

  function roundedRect(x, y, w, h, r) {
    ctx.beginPath(); ctx.roundRect(x, y, w, h, r);
  }
  function court() {
    ctx.clearRect(0, 0, W, H);
    const bg = ctx.createLinearGradient(0, 0, W, H);
    bg.addColorStop(0, '#d58a50'); bg.addColorStop(.52, '#c87943'); bg.addColorStop(1, '#b96738');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
    // Warm maple planks
    for (let y = 0; y < H; y += 46) {
      ctx.fillStyle = y % 92 === 0 ? 'rgba(255,215,155,.055)' : 'rgba(83,38,19,.045)';
      ctx.fillRect(0, y, W, 45);
      ctx.strokeStyle = 'rgba(83,42,22,.15)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(0, y + 45); ctx.lineTo(W, y + 45); ctx.stroke();
      const offset = (Math.floor(y / 46) % 2) * 55;
      for (let x = offset; x < W; x += 110) {
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 45); ctx.stroke();
      }
    }
    // Court markings
    ctx.strokeStyle = 'rgba(255,239,210,.67)'; ctx.lineWidth = 2.2;
    ctx.strokeRect(20, 20, 380, 530);
    ctx.beginPath(); ctx.moveTo(20, 215); ctx.lineTo(400, 215); ctx.stroke();
    ctx.beginPath(); ctx.arc(210, 215, 54, 0, Math.PI, true); ctx.stroke();
    ctx.beginPath(); ctx.arc(210, 215, 8, 0, Math.PI * 2); ctx.stroke();
    // Key and restricted area
    ctx.strokeRect(116, 20, 188, 168);
    ctx.beginPath(); ctx.arc(210, 188, 68, 0, Math.PI); ctx.stroke();
    ctx.beginPath(); ctx.arc(210, 188, 68, Math.PI, Math.PI * 2); ctx.stroke();
    // Three point arc
    ctx.beginPath(); ctx.arc(210, 154, 174, .18, Math.PI - .18); ctx.stroke();
    // Hoop/backboard detail
    ctx.fillStyle = 'rgba(40,39,30,.25)'; roundedRect(167, 47, 86, 7, 2); ctx.fill();
    ctx.fillStyle = '#ece6d3'; roundedRect(165, 42, 90, 6, 2); ctx.fill();
    ctx.strokeStyle = '#6e3925'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(186, 48); ctx.lineTo(234, 48); ctx.stroke();
    ctx.strokeStyle = '#f2eee0'; ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(210, 63, 24, 8, 0, 0, Math.PI * 2); ctx.stroke();
    // Net
    ctx.strokeStyle = 'rgba(255,244,221,.67)'; ctx.lineWidth = 1;
    for (let i = -3; i <= 3; i++) {
      const x = 210 + i * 6;
      ctx.beginPath(); ctx.moveTo(210 + i * 7.5, 65); ctx.lineTo(x, 84); ctx.stroke();
    }
    ctx.beginPath(); ctx.moveTo(190, 70); ctx.lineTo(230, 70); ctx.moveTo(194, 77); ctx.lineTo(226, 77); ctx.stroke();
    // Subtle court labels
    ctx.fillStyle = 'rgba(255,241,213,.38)'; ctx.font = '500 8px "DM Mono", monospace'; ctx.textAlign = 'left';
    ctx.fillText('BUCKETS // 01', 27, 38);
    ctx.textAlign = 'right'; ctx.fillText('HOME COURT', 393, 38);
  }
  function drawPlayer() {
    // Player shadow
    ctx.fillStyle = 'rgba(51,26,17,.24)'; ctx.beginPath(); ctx.ellipse(ball.x, ball.y + 44, 30, 8, 0, 0, Math.PI * 2); ctx.fill();
    // Legs / sneakers
    ctx.strokeStyle = '#e6d9bb'; ctx.lineWidth = 8; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(198, 443); ctx.lineTo(193, 459); ctx.moveTo(222, 443); ctx.lineTo(227, 459); ctx.stroke();
    ctx.strokeStyle = '#282c26'; ctx.lineWidth = 9; ctx.beginPath(); ctx.moveTo(192, 459); ctx.lineTo(184, 460); ctx.moveTo(228, 459); ctx.lineTo(236, 460); ctx.stroke();
    // Jersey silhouette
    ctx.fillStyle = '#253228'; ctx.beginPath(); ctx.moveTo(193, 407); ctx.lineTo(227, 407); ctx.lineTo(236, 443); ctx.lineTo(184, 443); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#d7e99c'; ctx.fillRect(205, 411, 10, 4);
    ctx.fillStyle = '#dfaa7d'; ctx.beginPath(); ctx.arc(210, 397, 12, 0, Math.PI * 2); ctx.fill();
    // Headband and arm lines
    ctx.fillStyle = '#f36b35'; ctx.fillRect(199, 390, 22, 4);
    ctx.strokeStyle = '#dfaa7d'; ctx.lineWidth = 7; ctx.beginPath(); ctx.moveTo(193, 413); ctx.lineTo(181, 425); ctx.moveTo(227, 413); ctx.lineTo(238, 424); ctx.stroke();
  }
  function drawBall(x, y, radius = 13, rotate = 0) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rotate);
    ctx.fillStyle = '#eb6b32'; ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#4d3023'; ctx.lineWidth = Math.max(1.2, radius * .11);
    ctx.beginPath(); ctx.arc(0, 0, radius * .97, -.95, .95); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, radius * .97, Math.PI - .95, Math.PI + .95); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-radius, 0); ctx.quadraticCurveTo(0, radius * .35, radius, 0); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-radius, 0); ctx.quadraticCurveTo(0, -radius * .35, radius, 0); ctx.stroke();
    ctx.restore();
  }
  function drawAim() {
    if (!dragging || !pointer) return;
    const dx = pointer.x - ball.x, dy = pointer.y - ball.y;
    const len = Math.hypot(dx, dy) || 1;
    const endX = ball.x + dx / len * Math.min(len, 375), endY = ball.y + dy / len * Math.min(len, 375);
    ctx.save();
    ctx.setLineDash([6, 7]); ctx.strokeStyle = 'rgba(244,255,207,.8)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ball.x, ball.y); ctx.quadraticCurveTo((ball.x + endX) / 2 - 25, (ball.y + endY) / 2, endX, endY); ctx.stroke();
    ctx.setLineDash([]); ctx.fillStyle = '#d6fa8b'; ctx.beginPath(); ctx.arc(endX, endY, 5, 0, Math.PI * 2); ctx.fill();
    const power = Math.min(100, Math.round(len / 3.2));
    ctx.fillStyle = 'rgba(19,24,17,.8)'; roundedRect(16, 503, 94, 31, 4); ctx.fill();
    ctx.fillStyle = '#c8f169'; ctx.font = '500 8px "DM Mono", monospace'; ctx.textAlign = 'left'; ctx.fillText(`POWER ${String(power).padStart(2, '0')}%`, 25, 516);
    ctx.fillStyle = '#48513f'; roundedRect(25, 522, 75, 3, 2); ctx.fill();
    ctx.fillStyle = '#c8f169'; roundedRect(25, 522, 75 * power / 100, 3, 2); ctx.fill();
    ctx.restore();
  }
  function drawShot(now) {
    if (!shot) return;
    const p = Math.min(1, (now - shot.started) / 720);
    const x = shot.from.x + (shot.to.x - shot.from.x) * p;
    const y = shot.from.y + (shot.to.y - shot.from.y) * p - Math.sin(p * Math.PI) * 126;
    drawBall(x, y, 13 - p * 3, p * 6);
    if (p >= 1 && !shot.resolved) {
      shot.resolved = true;
      window.setTimeout(() => { if (shot && shot.resolved) shot = null; }, 180);
    }
  }
  function render(now = performance.now()) {
    court();
    drawPlayer();
    if (shot) drawShot(now); else drawBall(ball.x, ball.y, 13, now / 500);
    drawAim();
    if (state === 'ready') {
      ctx.fillStyle = 'rgba(22,27,19,.62)'; roundedRect(16, 503, 129, 31, 4); ctx.fill();
      ctx.fillStyle = '#e9e9d8'; ctx.font = '500 8px "DM Mono", monospace'; ctx.textAlign = 'left'; ctx.fillText('READY WHEN YOU ARE', 25, 522);
    }
    requestAnimationFrame(render);
  }
  function startGame() {
    score = 0; streak = 0; timeLeft = 60; shot = null; pointer = null;
    scoreEl.textContent = '00'; streakEl.textContent = '0'; timerEl.innerHTML = '60<span class="seconds">s</span>';
    state = 'playing'; overlay.classList.add('hidden'); shootButton.disabled = false;
    lastFrame = performance.now();
  }
  function endGame() {
    state = 'over'; shootButton.disabled = true;
    overlay.classList.remove('hidden');
    const card = document.querySelector('#overlayCard');
    card.innerHTML = `<div class="overlay-icon">${score >= best ? '🏆' : '⏱️'}</div><p class="eyebrow">FINAL SCORE · ${score} POINTS</p><h2>${score >= best && score > 0 ? 'NEW<br><span>RECORD.</span>' : 'RUN IT<br><span>BACK.</span>'}</h2><p class="overlay-copy">${score >= best && score > 0 ? 'That court is yours. A new personal best.' : 'The clock ran out. Lace up and take another run.'}</p><button class="play-button" id="playAgain"><span>PLAY AGAIN</span><b>↗</b></button><span class="overlay-foot">BEST RUN · ${String(best).padStart(2, '0')} POINTS</span>`;
    document.querySelector('#playAgain').addEventListener('click', startGame);
  }
  function tick(now) {
    if (state === 'playing') {
      const elapsed = (now - lastFrame) / 1000;
      if (elapsed >= 1) {
        timeLeft = Math.max(0, timeLeft - Math.floor(elapsed));
        lastFrame = now;
        timerEl.innerHTML = `${timeLeft}<span class="seconds">s</span>`;
        timerEl.classList.toggle('urgent', timeLeft <= 10);
        if (timeLeft <= 0) endGame();
      }
    }
    requestAnimationFrame(tick);
  }
  function showFeedback(text, sub = '', miss = false) {
    feedback.innerHTML = `${text}${sub ? `<small>${sub}</small>` : ''}`;
    feedback.classList.remove('show', 'miss'); void feedback.offsetWidth;
    if (miss) feedback.classList.add('miss'); feedback.classList.add('show');
  }
  function playSound(good) {
    if (!soundOn) return;
    try {
      const audio = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = audio.createOscillator(), gain = audio.createGain();
      oscillator.type = 'sine'; oscillator.frequency.value = good ? 660 : 180;
      gain.gain.setValueAtTime(.08, audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .22);
      oscillator.connect(gain); gain.connect(audio.destination); oscillator.start(); oscillator.stop(audio.currentTime + .23);
      oscillator.onended = () => audio.close();
    } catch (_) { /* Audio is optional. */ }
  }
  function shoot(target) {
    if (state !== 'playing' || shot) return;
    const dx = target.x - ball.x, dy = target.y - ball.y;
    const len = Math.hypot(dx, dy);
    if (len < 26) { showFeedback('AIM UP', 'DRAG TOWARD THE HOOP', true); return; }
    const baseX = hoop.x - ball.x, baseY = hoop.y - ball.y;
    const angle = Math.acos(Math.max(-1, Math.min(1, (dx * baseX + dy * baseY) / (len * Math.hypot(baseX, baseY))))) * 180 / Math.PI;
    const power = len / Math.hypot(baseX, baseY);
    const made = angle < 11 && power > .69 && power < 1.38;
    const swish = made && angle < 3.2 && power > .86 && power < 1.15;
    let end = { x: hoop.x + (target.x - (ball.x + (hoop.y - ball.y) * dx / dy)), y: 90 };
    if (!Number.isFinite(end.x)) end.x = hoop.x + 70;
    end.x = Math.max(35, Math.min(385, end.x));
    if (made) end.x = hoop.x + (angle < 6 ? 0 : (dx > 0 ? 8 : -8));
    else if (Math.abs(end.x - hoop.x) < 10) end.x += dx >= 0 ? 35 : -35;
    shot = { from: { ...ball }, to: end, started: performance.now(), resolved: false };
    lastAim = { ...target };
    window.setTimeout(() => {
      if (state !== 'playing') return;
      if (made) {
        streak++;
        const points = 2 + (streak % 3 === 0 ? 1 : 0);
        score += points; scoreEl.textContent = String(score).padStart(2, '0');
        streakEl.textContent = String(streak);
        if (score > best) { best = score; bestEl.textContent = String(best).padStart(2, '0'); localStorage.setItem('buckets-best', String(best)); }
        showFeedback(swish ? 'SWISH!' : 'BUCKET!', points > 2 ? `+${points} POINTS · STREAK BONUS` : `+${points} POINTS`);
      } else {
        streak = 0; streakEl.textContent = '0'; showFeedback(angle > 17 ? 'OFF LINE' : 'NO GOOD', 'RESET YOUR AIM', true);
      }
      playSound(made);
      window.setTimeout(() => { if (state === 'playing') shot = null; }, 360);
    }, 690);
  }
